```go
package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"
	"path/filepath"

	"github.com/avocadoq/govc/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <main.go> <GoSourceFile>")
		return
	}

	goSourceFilePath := os.Args[1]
	structName := os.Args[2]

	// Parse the Go source file into an AST.
	file, err := parser.ParseFile(token.NewFileSet(), goSourceFilePath, nil, 0)
	if err != nil {
		fmt.Printf("Error parsing %s: %v\n", goSourceFilePath, err)
		os.Exit(1)
	}

	// Generate Avro schema for the struct.
	schemaGenerator := &schema.SchemaGenerator{
		TypeMap: map[string]string{},
	}
	for _, decl := range file.Decls {
		switch d := decl.(*ast.GenDecl); d.Tok {
		case token.TYPE:
			for i := range d.Specs {
				spec := d.Specs[i].(*ast.TypeSpec)
				if spec.Name.Name == structName {
					avroType, err := schemaGenerator.GenerateSchema(spec.Type)
					if err != nil {
						fmt.Printf("Error generating Avro schema for struct '%s': %v\n", structName, err)
						continue
					}
					fmt.Println(avroType)
					break
				}
			}
		}
	}
}
```

### Explanation:

1. **Main Function**: The program expects two command-line arguments (`main.go` and the name of the Go source file). It then calls the function `GenerateAvroSchema`.

2. **Parsing the Source File**: The `parser.ParseFile` function is used to parse the Go source file into an Abstract Syntax Tree (AST).

3. **Generating Schema**: The `schemaGenerator` object iterates through the parsed statements in the AST. For each type declaration, if the name matches the struct name provided as an argument, it attempts to generate an Avro schema.

4. **Outputting Schema**: If successful, the generated Avro schema is printed to the console.

### Usage:

To use this program, save the code above in a file called `main.go`, and compile it with `go build`. Then, execute the following command:

```sh
go run main.go your_go_source_file.go MyStructName
```

Replace `your_go_source_file.go` with the path to your Go source file and `MyStructName` with the name of the struct you want to convert.

This will create an `output/MyStructName.avsc` file containing the Avro schema for the struct defined in the source file.
